-- Ejecutar en SQL Editor para obtener estructura de public, NO filas de tablas de negocio.
-- Revisar y ocultar cualquier secreto literal que pudiera existir en cuerpos o defaults ANTES de compartir.
-- No envía datos, no modifica registros ni permisos.
WITH rels AS (SELECT c.oid,c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relacl,pg_get_userbyid(c.relowner) owner FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S','f')),
funcs AS (SELECT p.oid,p.proname,p.prokind,p.proacl,p.prosecdef,p.proconfig,pg_get_userbyid(p.proowner) owner,pg_get_function_identity_arguments(p.oid) args,CASE WHEN p.prokind IN ('f','p','w') THEN pg_get_functiondef(p.oid) ELSE NULL END definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'),
cols AS (SELECT r.relname,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod) type,a.attnotnull,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid) default_expression FROM rels r JOIN pg_attribute a ON a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=r.oid AND d.adnum=a.attnum),
cons AS (SELECT r.relname,c.conname,c.contype,pg_get_constraintdef(c.oid,true) definition FROM rels r JOIN pg_constraint c ON c.conrelid=r.oid),
trgs AS (SELECT r.relname,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true) definition FROM rels r JOIN pg_trigger t ON t.tgrelid=r.oid WHERE NOT t.tgisinternal),
views AS (SELECT relname,pg_get_viewdef(oid,true) definition FROM rels WHERE relkind IN ('v','m'))
SELECT jsonb_build_object('server_version',current_setting('server_version'),'relations',(SELECT coalesce(jsonb_agg(to_jsonb(r) - 'oid' ORDER BY relname),'[]'::jsonb) FROM rels r),'columns',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY relname,attnum),'[]'::jsonb) FROM cols c),'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY relname,conname),'[]'::jsonb) FROM cons c),'triggers',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY relname,tgname),'[]'::jsonb) FROM trgs t),'functions',(SELECT coalesce(jsonb_agg(to_jsonb(f) - 'oid' ORDER BY proname,args),'[]'::jsonb) FROM funcs f),'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname),'[]'::jsonb) FROM pg_policies p WHERE schemaname='public'),'indexes',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY tablename,indexname),'[]'::jsonb) FROM pg_indexes i WHERE schemaname='public'),'views',(SELECT coalesce(jsonb_agg(to_jsonb(v) ORDER BY relname),'[]'::jsonb) FROM views v),'sequences',(SELECT coalesce(jsonb_agg(to_jsonb(s) - 'last_value' ORDER BY sequencename),'[]'::jsonb) FROM pg_sequences s WHERE schemaname='public'),'roles',(SELECT coalesce(jsonb_agg(rolname ORDER BY rolname),'[]'::jsonb) FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role','postgres')),'extensions',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',extname,'version',extversion) ORDER BY extname),'[]'::jsonb) FROM pg_extension)) AS esquema_jaguar360;
